<!--
/* JavaScript functions to lookup and apply WMA/MLDR factors to 
 * track and field athletics performances.
 * Howard Grubb, 1999-2025
 * http://www.howardgrubb.co.uk/athletics
 *
 * January 2015 - updated road factors from WMA
 * November 2015 - reduce to road events only (separate track-and-field calculator)
 * June 2017 - stop extrapolation of standards
 * March 2018 - link to Walks
 * December 2019 - uneditable Age-graded cell
 * June 2020 - 2020 Road Tables (USATF MLDR)
 * November 2024 - modify code
 * January 2025 - update with 2025 Road Tables
 * July 2025 - update M 1Mile
 *
*/

"use strict";

// "global" variables that are populated as the form changes
var age = 25; // years
var iage = 20; // index of age in array of ages (to use in the array of factors for the event)
var iage1 = 20; // index above the age (if interpolating ages)
var page = 0; // proportion of year between iage and iage1

var dist = 0; // distance value km (converted)
var ifac = -1; // index of event in array
var ifac1 = -1; // index above the event (if interpolating distances)
var pfac = 0; // proportion of distance between ifac and ifac1 for interpolation

var lastDir = 1; // direction of calculation
var keepGender = 'M';
var form; // populated once form is loaded - method init_form() below

//=======================================================================================
class facrow {
    /* object to hold event name, distance, standard and age factors */
    constructor(event_name) {
        this.event_name = event_name; // string event name
        this.distance = arguments[1]; // distance (for running events)
        this.standard = arguments[2]; // third argument is the WMA age-standard
        this.ageFactors = new Array(); // put all the ageFactors in here - any # of args
        for (let i=3; i < arguments.length; i++) {
            this.ageFactors[i - 3] = arguments[i]; // these need to be the same length as Factors.ages
        }
    }
}
class Factors {
    /* store YEAR - SEX factors for list of events */
    constructor() {
        this.nage = 0;
        this.ages = new Array(); // not necessary?
        this.nfac = 0;
        this.facs = new Array(); // facrows for events
    }
    addAges(ages) {
        this.ages = ages;
        this.nage = ages.length;
    }
    addEvent(facrow) {
        // keep the same "structure" for now
        this.facs[this.nfac] = facrow; // previous structure
        this.nfac += 1; // can just use this.facs.length
    }
    // call this once all data are populated
    checkEvents(name) {
        let err = '';
        for (let i=0; i<this.nfac; i++) {
            if (this.facs[i].ageFactors.length !== this.ages.length) {
                err += " " + this.facs[i].event_name;
            }
        }
        if (err !== '') {
            console.log("AGE DISCREPANCY: " + name + ": " + err);
        }
    }
}

