//=====================================================================
function setEventOptions() // update event list when factors change
//=====================================================================
{
    let optList = form.road;
    let selEvent = optList.options[optList.selectedIndex].value;
    optList.options.length = 0;
    optList.options[0] = new Option("Select", "");
    // changes selectedIndex
    for (let i=0; i < factors.nfac; i++) {
        let thisEvent = factors.facs[i].event_name;
        let isSel = false;
        if (thisEvent == selEvent) {
            isSel = true;
            optList.selectedIndex = i+1;
        }
        optList.options[i+1] = new Option(thisEvent.replace("Road", ""), thisEvent, true, isSel);
    }
}
//=====================================================================
function roundval(value, dps)
//=====================================================================
{
    return Math.floor(value * Math.pow(10, dps) + 0.5) / Math.pow(10, dps);
}
//=====================================================================
function roundval1(value, dps) // separate function, in case it causes problems
//=====================================================================
{
    value = Math.floor(value  *Math.pow(10, dps) + 0.5) / Math.pow(10, dps);
    if (value < 1.0) {
        value = "0" + value; // show 0.xxx - does this ever fall over? Yes, with IE - modified below
        if (value.substring(0, 2) == "00") value = value.substr(1);
    }
    return value;
}
//=====================================================================
function hms_colon(str, sep)
//=====================================================================
{
    let sec = 0.0;
    let poscols = str.lastIndexOf(sep); // can't handle mixed separators
    if (poscols > 0) {
        if ((poscols + 1) < str.length) sec = parseFloat(str.substr(poscols+1));
        let poscolm = str.substring(0, poscols - 1).lastIndexOf(sep);
        if (poscolm > 0) sec += parseFloat(str.substring(0, poscolm)) * 3600;
        sec += parseFloat(str.substring(poscolm + 1, poscols)) * 60;
    }
    return sec;
}
//=====================================================================
function string_hms(str) // extract sec.dec from (hr:)min:sec string
//=====================================================================
{
    let sec = 0.0;
    sec = hms_colon(str, ':');
    if (sec == 0) {
        sec = hms_colon(str, ';'); // can separate with semi-colons
    }
    if (sec == 0) {
        sec = parseFloat(str); // default is just seconds
    }
    return sec;
}
//=====================================================================
function hms_string(val) // turn sec.dec into (hr:)min:sec string
//=====================================================================
{
    if (val > 0) { // how does this handle strings?
        let ndec = 1; // default
        if (val >= 3600) ndec = 0;
        if (val < 60) ndec = 2;
        val = roundval(val, ndec);

        let hrps = Math.floor(val / 3600.);
        let minps = Math.floor((val - hrps * 3600) / 60.);
        let secps = roundval1((val - hrps * 3600 - minps * 60), ndec); // possible rounding errors!

        if (hrps > 0 && minps < 10) minps = "0" + minps;
        if ((hrps > 0 || minps > 0 ) && secps < 10) secps = "0" + secps;
        if (hrps > 0) {
            return hrps + ":" + minps + ":" + secps;
        } else {
            if (minps > 0) {
                return minps + ":" + secps ;
            } else {
                return secps;
            }
        }
    } else {
        return val;
    }
}
//=================== end of generic functions (for now)

//=====================================================================
function setFactors(gender=keepGender)
//=====================================================================
{
    if (gender == 'M') {
        keepGender = gender; // could query control on page?
        switch (form.wmavsn.selectedIndex) {
            case 0:
                factors = MLDR_25_M_facs;
                break;
            case 1:
                factors = MLDR_20_M_facs;
                break;
            case 2:
                factors = WMA_15_M_facs;
                break;
            case 3:
                factors = WMA_10_M_facs;
                break;
        }
    } else if (gender == 'F') {
        keepGender = gender;
        switch (form.wmavsn.selectedIndex) {
            case 0:
                factors = MLDR_25_F_facs;
                break;
            case 1:
                factors = MLDR_20_F_facs;
                break;
            case 2:
                factors = WMA_15_F_facs;
                break;
            case 3:
                factors = WMA_10_F_facs;
                break;
        }
    } else {
        console.log("Missing gender in setFactors"); // can't happen?
    }
    setEventOptions();
    if (form.mileage.value == "") {
        setEvent();
    } else {
        setMileage();
    }
    lookup_factor(form);
}
//=====================================================================
function setEvent() // from list (could use a key to look them up)
//=====================================================================
{
    if (form.road.selectedIndex >= 0) {
        ifac = -1; // switch off
        for (let i=0; i < factors.nfac; i++) { // find matching event name
            if (factors.facs[i].event_name == form.road[form.road.selectedIndex].value) {
                ifac = i;
                ifac1 = i;
                pfac = 0;
            }
        } // what if not found? bad things ...
        // remove mileage if event selected
        form.mileage.value = "";
        form.mileage.placeholder = "or distance";
        lookup_factor(form);
    }
}
//=====================================================================
function setMileage()
//=====================================================================
{
    if (form.mileage.value > 0) {
        form.road.selectedIndex = 0;
        dist = form.mileage.value * form.milkm.value; // assume this
    
        let i = -1; // find the first event longer than the chosen distance
        while ((i < (factors.nfac-1) && factors.facs[i+1].distance <= dist) ||
               (i == (factors.nfac-1) && factors.facs[i].distance < dist) ) {
            i++;
        }

        ifac = i;
        if (i >= 0 && i < (factors.nfac-1)) {
            ifac1 = i+1;  // within array
        } else {
            ifac1 = i; // at the end or off it
        }

        if (ifac >=0 && ifac1 < factors.nfac) { // need interpolation/extrapolation
            if(ifac == ifac1) {
                pfac = 0; // take either end
            } else {
                pfac = (dist - factors.facs[ifac].distance) / (factors.facs[ifac1].distance - factors.facs[ifac].distance);
            }
        }

        lookup_factor(form);
    }
//  form.debug.value = dist + ' ' + ifac + ' ' + ifac1 + ' ' + ' ' + pfac;
}
//=====================================================================
function setAge()
//=====================================================================
{
    if (form.ageBox.value > 0) {
        age = form.ageBox.value;
        if (age == "") age = 29; // what about those factors which are >1.0?

        iage = -1;
        iage1 = 0;
        let i = 0; // find the first age older than the chosen
        while (i < factors.nage && factors.ages[i] < age) { i++; }
 
        if (i == 0) { iage = 0; iage1 = 0;} // younger fix at youngest
        if (i >= factors.nage - 1) { iage1 = factors.nage - 1; iage = factors.nage - 1;} // older fix at oldest
        if (i > 0 && i < factors.nage - 1) { iage = i - 1; iage1 = i; } // within array
 
        if (factors.ages[iage] != age && iage != iage1) { // need interpolation/extrapolation
            page = (age - factors.ages[iage]) / (factors.ages[iage1] - factors.ages[iage]);
        }
        lookup_factor(form);
    }
//  form.debug.value = age + ' ' + iage + ' ' + iage1 + ' ' + ' ' + page;
}
//=====================================================================
function lookup_factor(form) // lookup WMA factor in arrays
//=====================================================================
{
    let fac = 0.0; // bad
    if (iage >= 0 && ifac >= 0 && ifac1 < factors.nfac) { // only lookup ages, o/w take factor as 1.0
        fac =  factors.facs[ifac].ageFactors[iage];
        let faca = factors.facs[ifac].ageFactors[iage1];
        let fac1 = factors.facs[ifac1].ageFactors[iage];
        let fac1a = factors.facs[ifac1].ageFactors[iage1];
        fac = (1. - pfac) * (page * faca + (1. - page) * fac) +
                    pfac * (page * fac1a + (1. - page) * fac1);

        let std = (1. - pfac) * factors.facs[ifac].standard + pfac * factors.facs[ifac1].standard; // open-age standard
	
        form.afac.value = fac; // show factor to user
        form.ostd.value = std; // this will be in seconds
        form.astd.value = std / fac; // age-graded standard
        tidy_factor(form); // this rounds the age standard to nearest value
    } else {
        form.afac.value = '';
        form.ostd.value = '';
        form.astd.value = '';
    }
    form.ageresult.value = '';
    form.ageresult.placeholder = '';
    return fac;
}
//=====================================================================
function calc_fwd() // lookup factor and calculate age-grading etc.
//=====================================================================
{
    let fac = lookup_factor(form);
    if (fac == 0.0) {
        form.ageresult.value = '';
        form.aplp.value = '';
        form.ageresult.placeholder = 'select event';
        return;
    }
    let result = string_hms(form.result.value);
    let astd = string_hms(form.astd.value);
    if(result > 0) {
        form.ageresult.value = result * fac; // age-graded result
        if(astd > 0) {
            form.aplp.value = 100 * astd / result;
        }
        form.ageresult.placeholder = '';
        lastDir = 1;
    } else {
        form.ageresult.value = '';
        form.aplp.value = '';
        form.ageresult.placeholder = 'check result';
    }
    tidy_result(form);
}
//=====================================================================
function calc_back() // use age-standards to calculate a result for given PLP
//=====================================================================
{
    let fac = lookup_factor(form);
    if (fac == 0.0) {
        form.result.value = '';
        form.ageresult.value = '';
        form.ageresult.placeholder = 'select event';
        return;
    }
    var aplp = form.aplp.value;
//  form.debug.value = '|' + aplp + '|';
    var astd = string_hms(form.astd.value);
    var ostd = string_hms(form.ostd.value);
    if (aplp > 0 && astd > 0) {
        aplp /= 100.;
        form.result.value = astd / aplp;
        form.ageresult.value = ostd / aplp;
        form.ageresult.placeholder = '';
        lastDir = -1;
    } else {
        form.result.value = '';
        form.ageresult.value = '';
        form.ageresult.placeholder = 'check perf';
    }
    tidy_result(form);
}
//=====================================================================
function tidy_factor(form) // tidy up factors only
//=====================================================================
{
    if (form.ostd.value > 0) form.ostd.value = hms_string(form.ostd.value);
    if (form.astd.value > 0) form.astd.value = hms_string(form.astd.value);
    if (form.afac.value > 0) form.afac.value = roundval1(form.afac.value, 4);
}
//=====================================================================
function tidy_result(form) // tidy up results only
//=====================================================================
{
    if (form.result.value > 0) form.result.value = hms_string(form.result.value);
    if (form.ageresult.value > 0) form.ageresult.value = hms_string(form.ageresult.value);
    if (form.aplp.value > 0) form.aplp.value = roundval(form.aplp.value, 2);
}
//=====================================================================
function tidy_form(form) // tidy up results
//=====================================================================
{
    if (form.result.value > 0) form.result.value = hms_string(form.result.value);
    if (form.ageresult.value > 0) form.ageresult.value = hms_string(form.ageresult.value);
    if (form.ostd.value > 0) form.ostd.value = hms_string(form.ostd.value);
    if (form.astd.value > 0) form.astd.value = hms_string(form.astd.value);
    if (form.afac.value > 0) form.afac.value = roundval1(form.afac.value, 4);
    if (form.aplp.value > 0) form.aplp.value = roundval(form.aplp.value, 2);
}
//=====================================================================
function init_form() {
    form = document.dataform; // has to be defined once form is created
}
//=====================================================================

//-->
init_form();
